-- Generated by Loom
-- Generator: reference_table
-- Mode: latest
{{ config(materialized='view') }}
SELECT
    h.country_hk AS country_hk,
    h.country_code AS country_code,
    s.country_name AS country_name,
    s.__record_source AS __record_source,
    s.__loaded_at AS __loaded_at
FROM {{ ref('ref_country') }} AS h
JOIN (
    SELECT
        country_hk,
        country_name,
        __record_source,
        __loaded_at,
        ROW_NUMBER() OVER (
            PARTITION BY country_hk
            ORDER BY __loaded_at DESC, __hash_diff DESC
        ) AS rn
    FROM {{ ref('sat_country_details') }}
) AS s
    ON s.country_hk = h.country_hk
    AND s.rn = 1
